func TestRegexpHasIndicesNode18(t *testing.T) {
	// The d flag, which goja refused ("Invalid flags supplied to RegExp
	// constructor 'd'"), as Node.js 18 has it: hasIndices, flags and toString,
	// and the indices of a match and of its captures and named groups, with
	// exec, replace and matchAll, the u and y flags, and captures reset by an
	// iteration.
	const script = `
(function () {
	var out = [];
	function t(f) { try { out.push(f()); } catch (e) { out.push("E " + e.name + ": " + e.message); } }
	t(() => { var re = /a(b)?(?<n>c)?/d; var m = re.exec("xac"); var k = Object.keys(m); return [re.flags, re.hasIndices, m.indices, m.indices.groups, k[k.length - 1], Object.getOwnPropertyNames(m.indices)]; });
	t(() => { var re = new RegExp("(a)|(b)", "dg"); return ["ab".replace(re, "x"), re.flags, [...("ab".matchAll(re))].map(m => [m.indices, m.indices.groups])]; });
	t(() => new RegExp("a", "dd"));
	t(() => { var re = /(?<x>😀)(é)/du; var m = re.exec("a😀é"); return [m.indices, m.indices.groups, re.flags, String(re)]; });
	t(() => Object.getOwnPropertyDescriptor(RegExp.prototype, "hasIndices").get.call(RegExp.prototype));
	t(() => Object.getOwnPropertyDescriptor(RegExp.prototype, "hasIndices").get.call({}));
	t(() => { var d = Object.getOwnPropertyDescriptor(RegExp.prototype, "flags"); var o = {hasIndices: 1, global: 1, sticky: 1}; return d.get.call(o); });
	t(() => /a/.exec("a").indices);
	t(() => { var re = /a/dy; re.lastIndex = 1; var m = re.exec("ba"); return [m.indices, re.lastIndex]; });
	t(() => "xaby".match(/(?<n>a)(b)/d).indices);
	t(() => { var re = /(a)?/d; var m = re.exec(""); return [m.indices, 1 in m.indices, m.indices.length]; });
	t(() => typeof /a/d.exec("a").indices.groups);
	t(() => { var m = /(?<n>a)/d.exec("a"); return [Object.getPrototypeOf(m.indices.groups), Object.getOwnPropertyDescriptor(m, "indices")]; });
	t(() => Object.keys(Object.getOwnPropertyDescriptors(RegExp.prototype)).sort());
	t(() => /a/dgimsuy.flags);
	t(() => new RegExp(/a/d).flags + new RegExp(/a/d, "g").flags);
	t(() => { var m = /(?:(a)|b)+/d.exec("ab"); return m.indices; });
	return JSON.stringify(out);
})()
`
	testScript(script, newStringValue(`[["d",true,[[1,3],null,[2,3]],{"n":[2,3]},"indices",["0","1","2","length","groups"]],["xx","dg",[[[[0,1],[0,1],null],null],[[[1,2],null,[1,2]],null]]],"E SyntaxError: Invalid flags supplied to RegExp constructor 'dd'",[[[1,4],[1,3],[3,4]],{"x":[1,3]},"du","/(?<x>😀)(é)/du"],null,"E TypeError: RegExp.prototype.hasIndices getter called on non-RegExp object","dgy",null,[[[1,2]],2],[[1,3],[1,2],[2,3]],[[[0,0],null],true,2],"undefined",[null,{"value":[[0,1],[0,1]],"writable":true,"enumerable":true,"configurable":true}],["compile","constructor","dotAll","exec","flags","global","hasIndices","ignoreCase","multiline","source","sticky","test","toString","unicode"],"dgimsuy","dg",[[0,2],null]]`), t)
}

func TestRegexpEmptyIterationRefusedNode18(t *testing.T) {
	// ECMAScript refuses an iteration of a quantified group past its
	// minimum that matches nothing, and ends the loop before it; regexp2
	// takes one more such iteration, and Go's regexp takes the optional
	// copies of a bounded repeat that match nothing. Taken for the last
	// iteration, it dropped the real last iteration's captures:
	// /(?:(a)|(?=b))+b/.exec("ab") was ["ab", undefined] (Node.js 18:
	// ["ab", "a"]), and /(\B)*/ at lastIndex 2 on "b é" was ["", ""]
	// (Node.js 18: ["", undefined]). regexp2's refused iterations are
	// dropped, with the empty captures made in them; Go's captures of a loop
	// whose last iteration is such a copy are left as it gives them.
	const script = `
(function () {
	var out = [];
	var cases = [
		["(x)?(?:(b)|\\1)+a", "", "ba", 0], ["(?:(a)|(?=b))+b", "", "ab", 0], ["(?:(a)|(?!x))+b", "", "ab", 0],
		["(?:(a)|)+b", "g", "#ab", 1], ["(?:(\\w+)|\\s*)+$", "g", "#ab cd", 1], ["(?:\"([^\"]*)\"|,?)+$", "y", "#\"a\",\"b\"", 1],
		["(?:(\\d+)|\\.?)+$", "g", "#1.2", 1], ["(\\B)*", "g", "b é", 2], ["(\\B)*", "g", "b é", 3], ["(?:(\\B))*", "g", "b é", 2],
		["(?:(x*))+", "g", "#xx", 1], ["(?:(a)|(b?))+", "g", "#a", 1], ["(?:a(b?)|c?)+", "g", "#a", 1], ["(?:(?:a|)(b?))+", "g", "#a", 1],
		["(?:(?:(?:(b)(c)?|a|){2}x?){1,3})+?b", "", "bbb", 0], ["(x)?(?:(?:(?:b(a)?(a)b|(a+).){0,2}|b){1,3}){0,2}c", "g", "abc", 0],
		["(?:(a)|b|){2,}c", "g", "#abc", 1], ["(?:(a)|b?){1,3}$", "g", "#ab", 1], ["(?:(a)|(?=b)){2}b", "", "ab", 0],
		["(?<n>a|(?=b))+b", "g", "#ab", 1], ["(?:(?:(a)|b)+|(?=c))+c", "g", "#abc", 1],
	];
	for (var i = 0; i < cases.length; i++) {
		var c = cases[i], re = new RegExp(c[0], c[1]);
		re.lastIndex = c[3];
		var m = re.exec(c[2]);
		out.push(m ? [m.index].concat(Array.prototype.slice.call(m)) : null);
	}
	out.push("A b é".split(/()(?=(\B)*)/));
	out.push("#ab cd".replace(/(?:(\w+)|\s*)+$/g, "[$1]"));
	return JSON.stringify(out);
})()
`
	testScript(script, newStringValue(`[[0,"ba",null,"b"],[0,"ab","a"],[0,"ab","a"],[1,"ab","a"],[1,"ab cd","cd"],[1,"\"a\",\"b\"","b"],[1,"1.2","2"],[2,"",null],[3,"",null],[2,"",null],[1,"xx","xx"],[1,"a","a",null],[1,"a",""],[1,"a",""],[0,"bbb","b",null],[0,"abc",null,null,null,"a"],[1,"abc",null],[1,"ab",null],[0,"ab",null],[1,"ab","a"],[1,"abc",null],["A","",null," ","",null,"b","",null," ","",null,"é"],"#[cd][]"]`), t)
}

func TestRegexpBackreferenceInOwnGroupNode18(t *testing.T) {
	// A backreference in the group it is to matches nothing in ECMAScript,
	// as the group is reset at each iteration of a quantified group it is
	// in; regexp2 matched it with the group's capture from the last
	// iteration, and so took another path: /x((a)\1|.){2,}(b)/ on "xaab"
	// gave its second group the first iteration's "a" (Node.js 18: the
	// second's), which the drop of earlier iterations' captures made
	// undefined. The parser writes it for regexp2 as an empty group.
	const script = `
(function () {
	var out = [];
	var cases = [["x((a)\\1|.){2,}(b)", "yd", "xaab", 0], ["((a)\\1|.){2,}(b)", "gd", "#aab", 1], ["(.|(\\1|(a+)(.)|.)+?){2,}(b)", "g", "aab", 0],
		["(.|(\\1|(a+)(.)|.)+?){2,}(b)", "g", "abab", 0], ["(?<n>a\\k<n>)+", "d", "aaa", 0], ["(a(b\\2)\\1)*c", "g", "#ababc", 1], ["(a\\1)+", "", "aaa", 0]];
	for (var i = 0; i < cases.length; i++) {
		var c = cases[i], re = new RegExp(c[0], c[1]);
		re.lastIndex = c[3];
		var m = re.exec(c[2]);
		out.push(m ? [m.index].concat(Array.prototype.slice.call(m), m.indices ? [m.indices] : []) : null);
	}
	return JSON.stringify(out);
})()
`
	testScript(script, newStringValue(`[[0,"xaab","a","a","b",[[0,4],[2,3],[2,3],[3,4]]],[1,"aab","a","a","b",[[1,4],[2,3],[2,3],[3,4]]],[0,"aab","a",null,null,null,"b"],[0,"abab","a",null,null,null,"b"],[0,"aaa","a",[[0,3],[2,3]]],[1,"ababc","ab","b"],[0,"aaa","a"]]`), t)
}

func TestRegexpClassesRewrittenByTextNode18(t *testing.T) {
	// A class with property escapes, rewritten as its set ignoring case, is
	// written once for each text: [^\p{Nd}] is not [\p{Nd}].
	const script = `
(function () {
	var out = [];
	var pats = [["[\\p{Nd}][^\\p{Nd}]", "iu", "1a"], ["[^\\p{Nd}][\\p{Nd}]", "iu", "a1"], ["[\\p{L}][^\\p{L}]", "iu", "a1"], ["[\\p{Nd}]+[^\\p{Nd}]+[\\p{Nd}]", "iu", "12ab3"], ["[\\p{Lu}][^\\p{Lu}]", "u", "Ab"], ["[\\P{Nd}][\\p{Nd}]", "iu", "x9"]];
	for (var i = 0; i < pats.length; i++) out.push(new RegExp(pats[i][0], pats[i][1]).exec(pats[i][2]));
	return JSON.stringify(out);
})()
`
	testScript(script, newStringValue(`[["1a"],["a1"],["a1"],["12ab3"],["Ab"],["x9"]]`), t)
}

func TestRegexpDeepLoopsWithoutHiddenGroupsNode18(t *testing.T) {
	// A pattern whose hidden groups (see parser.Iterations) would nest its
	// groups past what Go's regexp takes is compiled without them, as it
	// was before them: 400 nested quantified groups with alternatives and
	// captures were refused ("expression nests too deeply").
	const script = `
(function () {
	var out = [];
	for (var n of [340, 400, 490]) {
		var p = "(?:(x)|".repeat(n) + ")*".repeat(n);
		var re = new RegExp(p), m = re.exec("xx");
		out.push([n, m[0], m.length]);
		re = new RegExp(p, "g");
		re.lastIndex = 1;
		m = re.exec("xx");
		out.push([n, m.index, m[0], m.length]);
	}
	return JSON.stringify(out);
})()
`
	testScript(script, newStringValue(`[[340,"xx",341],[340,1,"x",341],[400,"xx",401],[400,1,"x",401],[490,"xx",491],[490,1,"x",491]]`), t)
}

func TestRegexpEmptyIterationInRefusedNode18(t *testing.T) {
	// A loop whose last iteration is an empty one at where a loop it is in
	// had one refused may have had it in the refused one: its captures are
	// left to the loop it is in (see skipRefused), and are those of the
	// last iteration that loop kept. Dropped by the inner loop instead,
	// they were undefined: /(?=)(?:(?:|(\w+)){1,}){1,}$/.exec("ab") was
	// ["ab", undefined] (Node.js 18: ["ab", "ab"]).
	const script = `
(function () {
	var out = [];
	var cases = [["(?=)(?:(?:|(\\w+)){1,}){1,}$", "", "ab", 0], ["((?:(.)\\B|){1,}){1,}(?=b)", "y", "ab", 0], ["(?:x?(?:(?!b)(?!b)(a?)|)+(?:)*?)+b", "y", "ab", 0],
		["(?=)(?:(?:|(\\w+))+)+$", "", "ab cd", 0], ["(?:(?:|(\\w+)){1,}){1,}$", "g", "#ab", 1]];
	for (var i = 0; i < cases.length; i++) {
		var c = cases[i], re = new RegExp(c[0], c[1]);
		re.lastIndex = c[3];
		var m = re.exec(c[2]);
		out.push(m ? [m.index].concat(Array.prototype.slice.call(m)) : null);
	}
	return JSON.stringify(out);
})()
`
	testScript(script, newStringValue(`[[0,"ab","ab"],[0,"a","a","a"],[0,"ab","a"],[3,"cd","cd"],[1,"ab","ab"]]`), t)
}

func TestRegexpGoEmptyStarIterationNode18(t *testing.T) {
	// Go's regexp takes x* as (x+)? when x may match nothing, so that its
	// first iteration may be empty, which ECMAScript refuses: /(\s*)*/.exec("x")
	// was ["", ""] (Node.js 18: ["", undefined]), where regexp2's match
	// (lastIndex 1) dropped the iteration. Such an iteration, the only one
	// of its run, is dropped with the captures made in it.
	const script = `
(function () {
	var out = [];
	var cases = [["(\\s*)*", "x"], ["^(?:(\\d*)-?)*$", ""], ["(?:(a)|())*c", "c"], ["((a)|())*c", "c"], ["(?:(x*))*y", "y"], ["(?:(x?)(y?))*z", "z"],
		["(?:(a)|(b*))*$", "ab"], ["(?:(a*)b?)*c", "abc"], ["(\\s*)*?x", "x"], ["(?:(x*))+y", "y"], ["(?:a(x*))*b", "ab"], ["((?:(a)|())*)*c", "c"]];
	for (var i = 0; i < cases.length; i++) {
		var c = cases[i];
		out.push(new RegExp(c[0]).exec(c[1]));
		var g = new RegExp(c[0], "g");
		g.lastIndex = 1;
		out.push(g.exec("#" + c[1]));
		out.push(c[1].replace(new RegExp(c[0], "g"), "[$1]"));
	}
	return JSON.stringify(out);
})()
`
	testScript(script, newStringValue(`[["",null],["",null],"[]x[]",["",null],null,"[]",["c",null,null],["c",null,null],"[]",["c",null,null,null],["c",null,null,null],"[]",["y",null],["y",null],"[]",["z",null,null],["z",null,null],"[]",["ab",null,"b"],["ab",null,"b"],"[][]",["abc","a"],["abc","a"],"[a]",["x",null],["x",null],"[]",["y",""],["y",""],"[]",["ab",""],["ab",""],"[]",["c",null,null,null],["c",null,null,null],"[]"]`), t)
}
